WITH b(k, bucket, lo, hi) AS (VALUES (1, 'do 30 dni', 0, 30), (2, '31–60 dni', 31, 60), (3, '61–90 dni', 61, 90), (4, '91–180 dni', 91, 180), (5, 'ponad 180 dni', 181, 100000)), inv AS (SELECT object_id, CAST(json_extract(state,'$.open') AS BIGINT) AS open, date_diff('day', CAST(json_extract_string(state,'$.issue_date') AS DATE), {{today}}) AS age FROM objects WHERE object_type = 'sales_invoice' AND CAST(COALESCE(json_extract(state,'$.open'), '0') AS BIGINT) > 0) SELECT op, bucket, count, open, o AS _of FROM (SELECT b.k, '' AS op, b.bucket, COUNT(i.object_id) AS count, COALESCE(SUM(i.open), 0) AS open, COALESCE(string_agg(i.object_id, ',' ORDER BY i.object_id), '') AS o FROM b LEFT JOIN inv i ON i.age BETWEEN b.lo AND b.hi GROUP BY b.k, b.bucket UNION ALL SELECT 9, '=', 'Razem', COUNT(*), COALESCE(SUM(open), 0), COALESCE(string_agg(object_id, ',' ORDER BY object_id), '') FROM inv) ORDER BY k
